const rows = $input.all().map((item) => item.json);
const PAIRS = [
  { pairCode: "EUR_GBP", instrument: "EUR/GBP", base: "EUR", quote: "GBP" },
  { pairCode: "XAU_EUR", instrument: "XAU/EUR", base: "GOLD", quote: "EUR" },
  { pairCode: "XAG_EUR", instrument: "XAG/EUR", base: "SILVER", quote: "EUR" },
  { pairCode: "WTI_EUR", instrument: "WTI/EUR", base: "WTI", quote: "EUR" },
  { pairCode: "NQ_EUR", instrument: "NQ/EUR", base: "NQ", quote: "EUR" },
  { pairCode: "BTC_EUR", instrument: "BTC/EUR", base: "BTC", quote: "EUR" }
];
const LOW_CONVICTION_THRESHOLD = 60;

function parseMaybeJson(value, fallback = {}) {
  if (value === null || value === undefined || value === "") return fallback;
  if (typeof value === "object") return value;
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === "object" ? parsed : fallback;
  } catch (error) {
    return fallback;
  }
}

function toNumber(value) {
  if (value === null || value === undefined || value === "") return null;
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : null;
}

function clamp(value, min = 0, max = 100) {
  const numeric = toNumber(value);
  if (numeric === null) return null;
  return Math.max(min, Math.min(max, Math.round(numeric)));
}

function normalizeDirection(value) {
  const raw = String(value || "PENDING").trim().toUpperCase().replace(/\s+/g, "_");
  if (["PENDING", "NO_24H_CALL", "NO_CLEAR_BIAS", "NEUTRAL", "MARKET_CLOSED", ""].includes(raw)) return "NO_CLEAR_BIAS";
  if (raw.includes("BULLISH") || raw.includes("LONG")) return "BULLISH";
  if (raw.includes("BEARISH") || raw.includes("SHORT")) return "BEARISH";
  return "NO_CLEAR_BIAS";
}

function outputFromRow(row) {
  return parseMaybeJson(row.full_output, parseMaybeJson(row.raw_agent_output, {}));
}

function timestampOf(row) {
  const value = Date.parse(row.created_at || row.generated_at || row.run_time_et || "");
  return Number.isFinite(value) ? value : 0;
}

function latestFor(agent) {
  const candidates = rows.filter((row) => row.agent_name === agent && Number(row.layer) === 1);
  candidates.sort((a, b) => timestampOf(b) - timestampOf(a));
  return candidates[0] || null;
}

function assetCall(agent) {
  const row = latestFor(agent);
  if (!row) return { direction: "NO_CLEAR_BIAS", conviction: null };
  const output = outputFromRow(row);
  const todayCall = output.today_call || {};
  return {
    direction: normalizeDirection(todayCall.direction || row.call_24h_direction || row.direction_24h || output.direction_24h),
    conviction: clamp(todayCall.confidence ?? row.call_24h_conviction ?? row.conviction_24h ?? output.conviction_24h)
  };
}

const assets = Array.from(new Set(PAIRS.flatMap((pair) => [pair.base, pair.quote])));
const calls = Object.fromEntries(assets.map((asset) => [asset, assetCall(asset)]));
const trade_opportunities = [];
const avoid_today = [];

function avoid(instrument, reason) {
  avoid_today.push({ instrument, reason });
}

for (const pair of PAIRS) {
  const base = calls[pair.base];
  const quote = calls[pair.quote];
  const quoteLabel = pair.quote;
  const confidence = clamp(((base.conviction ?? 0) + (quote.conviction ?? 0)) / 2);
  if (base.conviction === null || quote.conviction === null) {
    avoid(pair.instrument, "Missing 24H conviction from one or both Layer 1 assets.");
  } else if (base.direction === "NO_CLEAR_BIAS" || quote.direction === "NO_CLEAR_BIAS") {
    avoid(pair.instrument, "One or both assets have no clear 24H bias.");
  } else if (base.conviction < LOW_CONVICTION_THRESHOLD || quote.conviction < LOW_CONVICTION_THRESHOLD) {
    avoid(pair.instrument, "Mixed or low conviction 24H signals.");
  } else if (base.direction === quote.direction) {
    avoid(pair.instrument, "Both assets point in the same 24H direction, so there is no clear relative edge.");
  } else if (base.direction === "BULLISH" && quote.direction === "BEARISH") {
    trade_opportunities.push({ instrument: pair.instrument, direction: "BUY", confidence, reason: pair.base + " is independently bullish while " + quoteLabel + " is independently bearish during today's session." });
  } else if (base.direction === "BEARISH" && quote.direction === "BULLISH") {
    trade_opportunities.push({ instrument: pair.instrument, direction: "SELL", confidence, reason: quoteLabel + " is independently bullish while " + pair.base + " is independently bearish during today's session." });
  } else {
    avoid(pair.instrument, "Mixed 24H signals.");
  }
}

trade_opportunities
  .sort((a, b) => b.confidence - a.confidence)
  .forEach((opportunity, index) => { opportunity.rank = index + 1; });

const dashboard = {
  dashboard_meta: {
    last_updated_et: new Date().toISOString(),
    source: "eur_pair_layer2_agent_draft"
  },
  trade_opportunities,
  avoid_today
};

return [{ json: { file_content: JSON.stringify(dashboard, null, 2), dashboard } }];
